-- 915: IBF courses — card the Learning Outcomes + Brochure sections exactly
-- like the WSQ courses. Generated by
-- scripts/local-dev/generate-ibf-lo-brochure-migration.php (see its header
-- for the full rationale).
--
-- The 7 IBF descriptions used markup view.phtml's extractor cannot see:
-- `<h2>Brochure</h2>` (extractor expects "Course Brochure") and, on
-- TGS-2025052659, a styled-<span> pseudo-heading for Learning Outcomes.
-- Seeds the one missing learning_outcomes block, then strips the inline
-- duplicates so only the left-panel cards render the content.
--
-- Idempotent + partner-safe: SKU-joined exact-byte REPLACE no-ops when the
-- bytes are absent (already stripped, or a diverged partner row). Literals
-- hex-encoded for apply.php's utf8 connection.
--
-- brochure stripped: 7  lo stripped: 1  lo blocks seeded: 1  skipped: 0

SET @a_sdesc := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'short_description');

-- TGS-2022601648
UPDATE catalog_product_entity_text t
  JOIN catalog_product_entity e ON e.entity_id = t.entity_id AND e.sku = 0x5447532d32303232363031363438
   SET t.value = REPLACE(t.value, , '')
 WHERE t.attribute_id = @a_sdesc AND t.store_id = 0;


