  SELECT 0x436f75727365205447532d3230323530353236353920e28094204c6561726e696e67204f7574636f6d6573, 0x636f757273655f5447532d323032353035323635395f6c6561726e696e675f6f7574636f6d6573, , NOW(), NOW(), 1 FROM DUAL
